insert into public.admin_experience_repertoire_items (id,stage,title,description,age_groups,status,family,fallback_item_id) values ('66666666-6666-4666-8666-666666666666','surprise_connect','Baloane de săpun','Folosesc câteva baloane de săpun ca moment neașteptat de conectare, adaptând interacțiunea la vârsta copilului.',array['age_2','age_3','age_4_5','age_6_7','age_8_plus'],'active',null,null) on conflict (id) do nothing;
