insert into public.admin_experience_repertoire_items (id,stage,title,description,age_groups,status,family,fallback_item_id) values ('77777777-7777-4777-8777-777777777777','next_visit_thread','Țin minte ce îți place','Pornesc de la un personaj, univers, animal, temă sau alt interes pe care am descoperit că îl pasionează pe copil și îi spun că data viitoare îi pregătesc ceva legat de acel interes. Exemplu: «Știu că îți place Stitch. Data viitoare îți pregătesc eu ceva cu Stitch.»',array['age_2','age_3','age_4_5','age_6_7','age_8_plus'],'active','emotional_interest',null) on conflict (id) do nothing;
