insert into public.admin_experience_repertoire_items (id,stage,title,description,age_groups,status,family,fallback_item_id) values ('88888888-8888-4888-8888-888888888888','next_visit_thread','Ridică ștacheta','Dacă am descoperit o abilitate sau o mișcare fizică care îi place copilului, propun ca la vizita următoare să încercăm ceva nou sau puțin mai dificil. Exemple: «Data viitoare învățăm încă două mișcări.» / «Data viitoare încercăm un salt nou.»',array['age_4_5','age_6_7','age_8_plus'],'active','motor',null) on conflict (id) do nothing;
