insert into public.admin_experience_repertoire_items (id,stage,title,description,age_groups,status,family,fallback_item_id) values ('99999999-9999-4999-8999-999999999999','next_visit_thread','Următorul nivel','Dacă unui copil i-a plăcut să rezolve o provocare, îi spun că data viitoare îi voi pregăti una asemănătoare, dar nouă sau puțin mai dificilă. Exemplu: «Data viitoare îți pregătesc una și mai grea.»',array['age_4_5','age_6_7','age_8_plus'],'active','cognitive',null) on conflict (id) do nothing;
