insert into public.admin_experience_repertoire_items (id,stage,title,description,age_groups,status,family,fallback_item_id) values ('ffffffff-ffff-4fff-8fff-ffffffffffff','memorable_close','Ce ai făcut rămâne aici','Dacă situația permite, păstrăm o urmă a lucrului creat sau făcut de copil: expunem creația, păstrăm construcția pentru data viitoare sau marcăm într-un mod vizibil că acel lucru îi aparține.',array['age_3','age_4_5','age_6_7','age_8_plus'],'active',null,null) on conflict (id) do nothing;
