insert into public.admin_experience_repertoire_items (id,stage,title,description,age_groups,status,family,fallback_item_id) values ('12121212-1212-4121-8121-121212121212','memorable_close','Ritualul nostru','Construiesc în timp un mic element comun cu copilul — gest, parolă amuzantă, replică sau handshake — care poate fi reluat la vizitele următoare.',array['age_4_5','age_6_7','age_8_plus'],'active',null,null) on conflict (id) do nothing;
