insert into public.admin_experience_repertoire_items (id,stage,title,description,age_groups,status,family,fallback_item_id) values ('13131313-1313-4131-8131-131313131313','memorable_close','Surpriză finală','Închei vizita, când este potrivit, cu un mic moment neașteptat de «wow»: balon modelat, truc de magie potrivit vârstei, mini-moment cu baloane de săpun sau un mic obiect-surpriză dacă există ceva potrivit. Nu este obligatoriu la fiecare vizită.',array['age_2','age_3','age_4_5','age_6_7','age_8_plus'],'active',null,null) on conflict (id) do nothing;
insert into public.admin_experience_repertoire_age_overlays (item_id,age_group,validation_status,age_specific_note,restriction) values ('13131313-1313-4131-8131-131313131313','age_2','idea','Variantele concrete trebuie să respecte restricțiile lor de vârstă; nu combin cu Cadoul Becky de la vizita 3.','Nu folosesc trucuri sau obiecte care pot fi interpretate literal și introduse în nas.') on conflict (item_id,age_group) do nothing;
