alter table public.admin_experience_repertoire_items
  add column if not exists family text,
  add column if not exists fallback_item_id uuid references public.admin_experience_repertoire_items(id) on delete set null;

create table if not exists public.admin_experience_repertoire_age_overlays (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references public.admin_experience_repertoire_items(id) on delete cascade,
  age_group text not null check (age_group in ('age_2','age_3','age_4_5','age_6_7','age_8_plus')),
  validation_status text not null default 'idea' check (validation_status in ('idea','validated')),
  age_specific_note text,
  restriction text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (item_id, age_group)
);

create index if not exists admin_experience_repertoire_age_overlays_item_idx
  on public.admin_experience_repertoire_age_overlays(item_id);

update public.admin_experience_repertoire_items set fallback_item_id = '22222222-2222-4222-8222-222222222222' where id = '11111111-1111-4111-8111-111111111111';
update public.admin_experience_repertoire_items set fallback_item_id = '33333333-3333-4333-8333-333333333333' where id = '22222222-2222-4222-8222-222222222222';
